 utensils.visible=isCooking&&immersive==='cook';let stir=chosen==='ramen'?(t-stirStart<2?1:.25):.15;utensils.position.x=3+Math.sin(t*2)*.16*stir;utensils.position.z=1.8+Math.cos(t*2)*.1*stir;
