let immersive=null,viewOffset=0,flipStart=-99,stirStart=-99,cookAge=0;const cameraAim=new T.Vector3(0,.6,0);const closeViews={fire:{eye:[-.1,1.15,3.65],look:[-.6,.65,1.7]},water:{eye:[1.7,1.25,-4.3],look:[2.2,-.15,-18]},cook:{eye:[3.1,2.48,3.12],look:[3,1.34,1.3]}};
