function seatFront(seat){return [seat.x+Math.sin(seat.rot)*.85,seat.z+Math.cos(seat.rot)*.85]}
const destinations={fire:seatFront(seats.fire),water:seatFront(seats.water),cook:[3,2.7],focus:seatFront(seats.focus),note:seatFront(seats.note),idle:[.8,.1]};
// Navigation is pure XZ math; every edge, including exact endpoints, is swept.
const navCircles=[[-.6,1.7,.59],[-5,-1,.52],[4.9,-2,.52],[-5.4,2,.45],[5.6,1.6,.45],[-3.8,-4,.45]];
const navBoxes=[{x:-3,z:0,hx:1.6,hz:1.45,rot:0},{x:3,z:1.3,hx:.88,hz:.67,rot:0},{x:-1,z:-2.8,hx:.96,hz:.48,rot:0},...campChairs.map(c=>({...c,hx:.48,hz:.46}))];
function valid(x,z){if(x*x+z*z>=35.5)return false;const radius=.27;for(const [a,b,r] of navCircles)if(Math.hypot(x-a,z-b)<r+radius)return false;for(const o of navBoxes){const dx=x-o.x,dz=z-o.z,c=Math.cos(o.rot),sn=Math.sin(o.rot),lx=c*dx-sn*dz,lz=sn*dx+c*dz;if(Math.abs(lx)<o.hx+radius&&Math.abs(lz)<o.hz+radius)return false}return true}
function segmentClear(a,b){const n=Math.max(1,Math.ceil(Math.hypot(a[0]-b[0],a[1]-b[1])/.055));for(let i=0;i<=n;i++){const u=i/n;if(!valid(a[0]+(b[0]-a[0])*u,a[1]+(b[1]-a[1])*u))return false}return true}
function route(tx,tz,startPosition=avatar.position){const step=.2,startPoint=[startPosition.x,startPosition.z],target=[tx,tz];if(!valid(tx,tz)||!valid(...startPoint))return [];if(segmentClear(startPoint,target))return [new T.Vector3(tx,0,tz)];const key=(x,z)=>x+','+z,q=[],seen=new Map();let found=null;const sx=Math.round(startPoint[0]/step),sz=Math.round(startPoint[1]/step);for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++){const n=[sx+dx,sz+dz];if(segmentClear(startPoint,[n[0]*step,n[1]*step])){q.push(n);seen.set(key(...n),null)}}for(let i=0;i<q.length&&i<7000;i++){const n=q[i],point=[n[0]*step,n[1]*step];if(Math.hypot(point[0]-tx,point[1]-tz)<.31&&segmentClear(point,target)){found=n;break}for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){const v=[n[0]+dx,n[1]+dz],k=key(...v);if(!seen.has(k)&&segmentClear(point,[v[0]*step,v[1]*step])){seen.set(k,n);q.push(v)}}}if(!found)return [];let out=[];for(let n=found;n;n=seen.get(key(...n)))out.unshift([n[0]*step,n[1]*step]);out.push(target);let smooth=[],anchor=startPoint;for(let i=0;i<out.length;){let j=out.length-1;while(j>i&&!segmentClear(anchor,out[j]))j--;smooth.push(new T.Vector3(out[j][0],0,out[j][1]));anchor=out[j];i=j+1}return smooth}
let occupiedSeat=null,seatMotion=null;
function standThen(done){if(!occupiedSeat){done();return}const seat=occupiedSeat,front=seatFront(seat);seatMotion={kind:'stand',age:0,from:avatar.position.clone(),to:new T.Vector3(front[0],0,front[1]),seat,done};state='standing';path=[];status('의자 앞으로 일어나고 있어요.');}
function animateSeat(dt){if(!seatMotion)return;const m=seatMotion;m.age+=dt;const u=Math.min(1,m.age/.8),ease=u*u*(3-2*u);avatar.position.lerpVectors(m.from,m.to,ease);avatar.rotation.y=m.seat.rot;body.position.y=m.kind==='sit'?-.06*ease:-.06*(1-ease);legs.forEach(l=>{l.rotation.x=-1.4*(m.kind==='sit'?ease:1-ease);l.userData.knee.rotation.x=-l.rotation.x;l.userData.knee.scale.y=1+.65*(m.kind==='sit'?ease:1-ease)});if(u===1){seatMotion=null;if(m.kind==='stand')occupiedSeat=null;m.done()}}
const noteEl=document.querySelector('#sceneNote');function status(t){noteEl.textContent=t;document.querySelector('#avatarStatus').textContent=t}
function stopCooking(){if(document.querySelector('#cookBtn').textContent==='요리 멈추기')originalCook();}
function act(action){window.primeSceneSound();leaveView();standThen(()=>beginAct(action));}
function beginAct(action){if(action!=='cook')stopCooking();pending=action;const dest=destinations[action];path=route(...dest);state='walk';status(({fire:'모닥불 앞으로 걸어가요.',water:'바다를 보러 가요.',cook:'요리대로 걸어가요.',focus:'작업 테이블로 가요.',note:'노트를 쓰러 가요.',idle:'잠깐 쉬어갈게요.'})[action]);if(!path.length){state='idle';status('이 자리에서는 이동 경로를 찾지 못했어요. 캠프의 빈 곳을 눌러주세요.')}}
function arrive(){const seat=seats[pending];if(seat){occupiedSeat=seat;seatMotion={kind:'sit',age:0,from:avatar.position.clone(),to:new T.Vector3(seat.x+Math.sin(seat.rot)*.1,0,seat.z+Math.cos(seat.rot)*.1),seat,done:finishArrival};state='seating';status('의자 앞에서 천천히 앉고 있어요.');return}finishArrival()}
function finishArrival(){state=pending;body.position.y=seats[state]?-.26:0;avatar.rotation.y=seats[state]?.rot??(state==='cook'?Math.PI:0);status(({fire:'작은 불꽃을 바라보며 쉬고 있어요.',water:'밤바다를 바라보고 있어요.',cook:chosen==='ramen'?'라면이 보글보글 익어가요.':chosen==='fish'?'고등어를 노릇하게 굽고 있어요.':'삼겹살을 지글지글 굽고 있어요.',focus:'테이블에 앉았어요. 집중 시간을 골라주세요.',note:'오늘 마음에 남은 이야기는 무엇인가요?',idle:'편안히 쉬고 있어요.'})[state]);if(state==='cook'&&activeDish)status(activeDish.name+' — '+activeDish.sound);if(['fire','water','cook'].includes(state)){enterView(state);window.mixSceneSound(state)}if(state==='cook'&&document.querySelector('#cookBtn').textContent!=='요리 멈추기'){originalCook();cookAge=0;}if(state==='focus'||state==='note')window.openModal(state==='focus'?'focus':'note')}
const originalMode=window.setMode,originalCook=window.toggleCook,originalSelect=window.selectFood,originalModal=window.openModal,originalDay=window.toggleDay;
window.setMode=m=>{originalMode(m);act(m==='water'?'water':'fire')};window.toggleCook=async()=>{if(state==='cook'&&document.querySelector('#cookBtn').textContent==='요리 멈추기'){await originalCook();leaveView();window.mixSceneSound('camp');state='idle';status('요리를 마쳤어요.')}else act('cook')};window.selectFood=(f,b)=>{clearRegionalDish();originalSelect(f,b);chosen=f;potGroup.visible=f==='ramen';grill.visible=f!=='ramen';fishG.visible=f==='fish';meat.forEach(x=>x.visible=f==='pork');cookAge=0;if(state==='cook'){enterView('cook');window.mixSceneSound('cook');window.primeSceneSound()}else act('cook');if(state==='cook')status(f==='ramen'?'라면을 끓이고 있어요.':f==='fish'?'고등어를 굽고 있어요.':'삼겹살을 굽고 있어요.')};
window.openModal=id=>{if(id==='focus'||id==='note'){if(state!==id){act(id);return}}originalModal(id)};window.toggleDay=()=>{window.chooseTime(document.body.classList.contains('day')?'night':'morning')};

function enterView(mode){host.dataset.view=mode;immersive=mode;water.visible=true;viewOffset=0;host.classList.add('immersive');document.querySelector('#immersiveTools').hidden=false;document.querySelector('#immersiveLabel').textContent=mode==='fire'?'🔥 불멍':mode==='water'?'🌊 물멍':chosen==='ramen'?'🍜 라면 끓이기':chosen==='fish'?'🐟 고등어 굽기':'🥩 삼겹살 굽기';if(mode==='cook'&&activeDish)document.querySelector('#immersiveLabel').textContent=activeDish.emoji+' '+activeDish.action;let b=document.querySelector('#foodAction');b.hidden=mode!=='cook';b.textContent=chosen==='ramen'?(activeDish?'🥄 국물 젓기':'🥢 면 젓기'):(activeDish&&activeDish.id==='dakgalbi'?'🥢 볶아주기':'🥢 뒤집기');}
