window.returnToCamp=()=>{leaveView();stopCooking();standThen(()=>{state='idle';pending='idle';path=[];body.position.y=0;window.mixSceneSound('camp');status('캠프로 돌아왔어요. 다음엔 무엇을 해볼까요?')})};
