// Command input is deliberately local: supported intents, no external AI calls.
window.campCommand=text=>{let s=text.trim().replace(/\s/g,'');if(!s)return;document.querySelector('#command').value='';if(/고양이|야옹|냥이/.test(s)){window.visitCampCat();return}if(/멈|취소|일어나|그만/.test(s)){act('idle');return}if(/순두부|닭갈비|게국지|굴구이|흑돼지|지역음식|향토음식/.test(s)){window.quickRegionalDish();return}if(/고등어|생선|삼겹|고기|라면|요리/.test(s)){let f=/고등어|생선/.test(s)?'fish':/삼겹|고기/.test(s)?'pork':chosen;let b=document.querySelectorAll('.foodtabs button')[{fish:0,pork:1,ramen:2}[f]];window.selectFood(f,b);return}if(/집중|공부|작업|독서|책/.test(s)){let minutes=s.match(/(\d+)분/);if(minutes){let m=Number(minutes[1]);if(m>=1&&m<=180)window.setTimer(m);else{status('집중 시간은 1~180분으로 말해주세요.');return}}act('focus');return}if(/기록|한줄|노트|일기/.test(s)){act('note');return}if(/바다|물멍|파도/.test(s)){window.setMode('water');return}if(/불멍|모닥불|불앞/.test(s)){window.setMode('fire');return}if(/명상|호흡/.test(s)){originalModal('breath');return}if(/밤|낮/.test(s)){let wantDay=/낮/.test(s);if(wantDay!==document.body.classList.contains('day'))window.toggleDay();return}status('“불 앞에 앉아”, “라면 끓여줘”, “25분 집중”처럼 말해주세요.')};

